import pdfplumber, pandas as pd, re
from difflib import SequenceMatcher

vendors = pd.read_excel('/root/vendors.xlsx')

suffix_tokens = {'ltd', 'limited', 'corp', 'corporation', 'inc', 'incorporated', 'llc', 'co', 'company'}

punct_re = re.compile(r"[^a-z0-9\s]")

def normalize_name(name: str) -> str:
    s = name.lower().strip()
    s = s.replace('&', ' and ')
    s = punct_re.sub(' ', s)
    s = ' '.join(s.split())
    return s

def strip_suffixes(name: str) -> str:
    tokens = name.split()
    while tokens and tokens[-1] in suffix_tokens:
        tokens = tokens[:-1]
    return ' '.join(tokens)

vendor_records = []
for _, row in vendors.iterrows():
    name = str(row['name'])
    norm = normalize_name(name)
    stripped = strip_suffixes(norm)
    vendor_records.append({'id': row['id'],'name': name,'iban': str(row['iban']),'norm': norm,'stripped': stripped})

exact_norm_map = {v['norm']: v for v in vendor_records}
exact_stripped_map = {v['stripped']: v for v in vendor_records}

def best_vendor_match(vendor_name: str, cutoff: float = 0.85):
    norm = normalize_name(vendor_name)
    stripped = strip_suffixes(norm)
    if norm in exact_norm_map:
        return exact_norm_map[norm], 1.0
    if stripped in exact_stripped_map:
        return exact_stripped_map[stripped], 1.0
    best=None; best_score=0.0
    for v in vendor_records:
        score=SequenceMatcher(None, stripped, v['stripped']).ratio()
        if score>best_score:
            best_score=score; best=v
    if best_score>=cutoff:
        return best, best_score
    return None, best_score

# scan invoices
with pdfplumber.open('/root/invoices.pdf') as pdf:
    for idx, page in enumerate(pdf.pages, start=1):
        text = page.extract_text() or ''
        m = re.search(r"From:\s*(.+)", text)
        if not m:
            continue
        name = m.group(1).strip()
        vendor, score = best_vendor_match(name)
        if vendor is not None and score < 1.0:
            print(idx, name, '->', vendor['name'], score)
